{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify encryption for the root block device or additional block devices, which could lead to unencrypted data at rest."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not explicitly disable public IP address assignment, which could expose instances to the public internet."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The launch template does not enforce the use of HTTP tokens for the instance metadata service (IMDS), which could allow unauthorized access to sensitive metadata."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              export API_KEY="sk-1234567890abcdef"
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      delete_on_termination = true
      encrypted = true
    }
  }

  network_interfaces {
    associate_public_ip_address = false
  }

  metadata_options {
    http_tokens = "required"
    http_endpoint = "enabled"
  }
}",
  "fix_summary": "Added encryption for the root block device to ensure data at rest is secure. Disabled public IP address assignment to prevent unintended exposure to the internet. Enforced the use of HTTP tokens for the instance metadata service to enhance security."
}
